mapper.select:
SELECT l.*,
       t.name AS tenant_name,
       u.username AS username,
       u.real_name AS real_name
FROM ${log.database}.sys_operation_log l
LEFT JOIN ${log.database}.sys_tenant t ON t.id = l.tenant_id
LEFT JOIN ${log.database}.sys_user u ON u.id = l.user_id
WHERE 1=1

    AND l.tenant_id = #{tenantId}


    AND (t.name LIKE CONCAT('%', #{keyword}, '%')
         OR u.username LIKE CONCAT('%', #{keyword}, '%')
         OR u.real_name LIKE CONCAT('%', #{keyword}, '%')
         OR l.module LIKE CONCAT('%', #{keyword}, '%')
         OR l.action LIKE CONCAT('%', #{keyword}, '%')
         OR l.request_uri LIKE CONCAT('%', #{keyword}, '%'))


    AND l.is_success = #{isSuccess}


    AND l.operation_time >= #{startTime}


    AND l.operation_time <= #{endTime}



        ORDER BY t.name ${sortOrder}


        ORDER BY u.username ${sortOrder}


        ORDER BY u.real_name ${sortOrder}


        ORDER BY l.${sortField} ${sortOrder}


        ORDER BY l.operation_time DESC
